package android.os; public class Parcel { private final java.util.ArrayList<Object> data=new java.util.ArrayList<>(); private int pos; public static Parcel obtain(){return new Parcel();} public void recycle(){} public void writeInterfaceToken(String s){data.add(s);} public void enforceInterface(String s){if(!s.equals(data.get(pos++)))throw new SecurityException();} public void writeStrongBinder(IBinder b){data.add(b);} public IBinder readStrongBinder(){return (IBinder)data.get(pos++);} public void enforceNoDataAvail(){if(pos!=data.size())throw new IllegalArgumentException();} public void writeNoException(){data.add(0);} public void readException(){if(!Integer.valueOf(0).equals(data.get(pos++)))throw new RuntimeException();} public void writeInt(int x){data.add(x);} public int readInt(){return (Integer)data.get(pos++);} public void writeString(String x){data.add(x);} public void writeByteArray(byte[] x){data.add(x.clone());} public byte[] createByteArray(){return ((byte[])data.get(pos++)).clone();} }
